shots.draw_js:
clearScene();setBig(null);
setEq("$$J(w)=\\sum_s d(s)\\big(V^{\\pi}(s)-\\hat V(s;w)\\big)^2$$","top");
note("d(s) 是权重",640,310,"y lg");
setCap("参数不够用时，误差必须<b>有所取舍</b>。取舍的依据就是这个 d(s)。");

clearScene();setEq(null);
setBig("就是对状态取平均","均方误差嘛，一视同仁");
setCap("「均方误差」这个名字确实暗示一视同仁 —— <b>而它不是</b>。");

clearScene();setBig(null);
setEq("$$d(s')=\\sum_s\\sum_a d(s)\\,\\pi(a\\mid s)\\,P(s'\\mid s,a)$$","top");
note("策略跑出来的分布",640,300,"y lg");
note("对动作求和是为随机策略",640,360,"sm lg");
setCap("d 是策略诱导的<b>平稳分布</b>：你待得越久的状态，误差算得越重。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3,4,5,6],step:340,vals:[0.03,0.06,0.11,0.17,0.21,0.24,0.18],
  x:250,y:420,w:780,h:160,max:0.28,
  label:function(i){return "s"+(i+1);},
  cls:function(i){return i>=4?"y":"b";},
  fmt:function(v){return v.toFixed(2);}});
note("访问频率决定权重",640,466,"y");
setCap("同一组特征、同一份数据，<b>换个策略就换个 d</b>，于是换一组最优权重。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:300,items:[
  {label:"不是均匀",sub:"按访问频率加权",state:"on"},
  {label:"不是你选的",sub:"策略跑出来的",state:"on"},
  {label:"控制要另一个",sub:"她自己承认了",state:"dead"}]});
note("结论都相对于 d 成立",640,420,"y");
setCap("<b>指名反驳</b>：不是一视同仁，是<b>按你待的时间加权</b>，而且这个权重你说了不算。");

clearScene();setBig(null);setEq(null);
note("MC 收敛到哪",400,280,"b lg");
note("TD 收敛到哪",880,280,"v lg");
note("同一组特征，同一个 d",640,400,"y lg");
setCap("两条路都收敛。<b>但它们收敛到的不是同一组权重。</b>");

clearScene();setEq(null);
setBig("都收敛到最好的那组 w","既然都收敛，当然都收敛到最优逼近");
setCap("<b>只有 MC 是这样。</b>TD 收敛到另一个地方，而且可能差很远。");

clearScene();setBig(null);
setEq("$$\\mathrm{MSVE}(w_{TD})\\;\\le\\;\\frac{1}{1-\\gamma}\\min_w \\mathrm{MSVE}(w)$$","top");
note("注意是 ≤ 不是 =",640,310,"r lg");
setCap("Tsitsiklis–Van Roy：TD 落在最优逼近的 <b>1/(1−γ) 倍之内</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2],step:640,vals:[10,20,100],x:380,y:430,w:520,h:170,max:110,
  label:function(i){return ["γ=0.9","γ=0.95","γ=0.99"][i];},
  cls:function(i){return i===2?"r":"v";},
  fmt:function(v){return "×"+v.toFixed(0);}});
note("TD 允许差这么多倍",640,466,"r");
setCap("γ=0.99 时因子是 <b>100 倍</b> —— 而 0.99 是深度 RL 的默认值。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"MC",sub:"达到 min MSVE",state:"on"},
  {label:"TD",sub:"1/(1−γ) 倍之内",state:"dead"},
  {label:"讲座口误",sub:"两次把 ≤ 说成 =",state:"dead"}]});
note("这是界，不是实际差距",640,420,"y");
setCap("<b>指名反驳</b>：只有 MC 收敛到最优逼近。TD 收敛到另一个不动点。");

clearScene();setBig(null);setEq(null);
note("前四讲全用 TD 类",640,280,"b lg");
note("为什么没见过 100 倍",640,350,"y lg");
setCap("上一集那个 100 倍，在 L1–L4 里<b>一次都没出现过</b>。为什么？");

clearScene();setEq(null);
setBig("表格只是特征多一点","本质上和别的特征没区别");
setCap("表格<b>确实</b>只是一组特征 —— 但它是让误差下界归零的那一组。");

clearScene();setBig(null);
setEq("$$\\text{one-hot} \\;\\Longrightarrow\\; \\exists\\, w:\\ \\hat V(\\cdot;w)=V^{\\pi} \\;\\Longrightarrow\\; \\min_w \\mathrm{MSVE}=0$$","top");
note("真值就在可表示类里",640,310,"g lg");
setCap
("one-hot 的独有性质：<b>可表示的函数类装得下真值函数本身</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:800,vals:[0.001,0.001],x:380,y:430,w:520,h:170,max:1,
  label:function(i){return ["MC 的 MSVE","TD 的 MSVE"][i];},
  cls:function(i){return "g";},
  fmt:function(v){return "0";}});
note("100 × 0 还是 0",640,466,"g");
setCap("代进去：MC 误差 = 0，TD 误差 ≤ <b>100 × 0 = 0</b>。两者都精确为零。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"one-hot",sub:"真值在可表示类里",state:"on"},
  {label:"min MSVE = 0",sub:"不需要逼近",state:"on"},
  {label:"因子被吞掉",sub:"100 × 0 = 0",state:"on"}]});
note("前四讲站在这个 0 上",640,420,"y");
setCap("<b>指名反驳</b>：表格不是「特征多一点」，是<b>让误差下界归零</b>的那一组。");
